-- Generated by Rowlit from SQL Server. Parameters (@Name) are prompted for when you run a statement.

-- Registered customers
-- dbo.Customers: MERGE
MERGE INTO dbo.Customers AS t
USING (SELECT @Id AS Id, @Name AS Name, @Email AS Email, @CountryId AS CountryId) AS s
    ON t.Id = s.Id
WHEN MATCHED THEN
    UPDATE SET t.Name = s.Name, t.Email = s.Email, t.CountryId = s.CountryId
WHEN NOT MATCHED THEN
    INSERT (Name, Email, CountryId) VALUES (s.Name, s.Email, s.CountryId);

-- dbo.Orders: MERGE
MERGE INTO dbo.Orders AS t
USING (SELECT @Id AS Id, @CustomerId AS CustomerId, @OrderDate AS OrderDate, @Total AS Total) AS s
    ON t.Id = s.Id
WHEN MATCHED THEN
    UPDATE SET t.CustomerId = s.CustomerId, t.OrderDate = s.OrderDate, t.Total = s.Total
WHEN NOT MATCHED THEN
    INSERT (CustomerId, OrderDate, Total) VALUES (s.CustomerId, s.OrderDate, s.Total);

-- dbo.OrderLines: MERGE
MERGE INTO dbo.OrderLines AS t
USING (SELECT @OrderId AS OrderId, @ProductId AS ProductId, @Qty AS Qty) AS s
    ON t.OrderId = s.OrderId AND t.ProductId = s.ProductId
WHEN MATCHED THEN
    UPDATE SET t.Qty = s.Qty
WHEN NOT MATCHED THEN
    INSERT (OrderId, ProductId, Qty) VALUES (s.OrderId, s.ProductId, s.Qty);

