-- dbo.Events: MERGE
MERGE INTO dbo.Events AS t
USING (SELECT @EventId AS EventId, @OccurredAt AS OccurredAt, @Day AS Day, @At AS At, @Kind AS Kind, @Payload AS Payload, @Snapshot AS Snapshot, @Spec AS Spec, @Score AS Score, @Ratio AS Ratio, @Flags AS Flags, @Big AS Big, @Price AS Price, @IsActive AS IsActive, @Location AS Location) AS s
    ON t.EventId = s.EventId
WHEN MATCHED THEN
    UPDATE SET t.OccurredAt = s.OccurredAt, t.Day = s.Day, t.At = s.At, t.Kind = s.Kind, t.Payload = s.Payload, t.Snapshot = s.Snapshot, t.Spec = s.Spec, t.Score = s.Score, t.Ratio = s.Ratio, t.Flags = s.Flags, t.Big = s.Big, t.Price = s.Price, t.IsActive = s.IsActive, t.Location = s.Location
WHEN NOT MATCHED THEN
    INSERT (EventId, OccurredAt, Day, At, Kind, Payload, Snapshot, Spec, Score, Ratio, Flags, Big, Price, IsActive, Location) VALUES (s.EventId, s.OccurredAt, s.Day, s.At, s.Kind, s.Payload, s.Snapshot, s.Spec, s.Score, s.Ratio, s.Flags, s.Big, s.Price, s.IsActive, s.Location);

-- dbo.Keywords: MERGE
MERGE INTO dbo.Keywords AS t
USING (SELECT @Id AS Id, @class AS class, @type AS type, @select AS [select], @Keyword AS Keyword) AS s
    ON t.Id = s.Id
WHEN MATCHED THEN
